import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_parser_skips_comments_and_blanks_and_trims_fields():
    lines = ["", " \t", "  # comment", " x , 1 , 0 ", "y, 2, "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 1, "flagged": False},
        {"id": "y", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,extra", "a,no,1"])
def test_parser_error_counts_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["#header", "a,1,0", " ", bad])


def test_last_duplicate_id_wins_before_sorting():
    events = parse_transcript_log(["b,9,1", "z,1,1", "a,2,1", "b,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_daily_counts_and_windows():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,1", "e,4,0", "f,5,1"])
    counts = daily_flag_counts(events, 1, 4)
    assert counts == [2, 0, 1, 0]
    assert daily_flag_counts(events, 4, 1) == []
    assert flags_in_window(counts, 2) == 1
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 5) == 3


def test_summary_pools_transcripts_and_counts_calendar_days():
    groups = {"x": parse_transcript_log(["a,1,1", "b,4,0"]),
              "y": parse_transcript_log(["c,1,1"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": True}], "b": [], "a": [{"flagged": True}], "d": [{"flagged": False}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "d"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("d", 0.0), ("z", 1.0)]


def test_streak_counts_consecutive_positive_entries():
    assert longest_flag_streak([1, 0, 3, 2, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
